<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientRegistrationAccessAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientRegistrationAccessAccessor trait.
 *
 * Covers null default, string/VO assignment via withRegistrationAccess,
 * getRegistrationAccess/registrationAccess accessors, and isRegistrationAccessChanged with/without original.
 */
class TrustedClientRegistrationAccessAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRegistrationAccess creates a new instance with the RegistrationAccess set
     * from a string value, and getRegistrationAccess returns the primitive string.
     */
    public function testWithRegistrationAccessFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRegistrationAccessAccessorUnitTest();

        // Act
        $result = $holder->withRegistrationAccess('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getRegistrationAccess());
    }
    /**
     * Asserts that withregistrationAccess has access to the value object
     * from a string value, and getRegistrationAccess returns the primitive string.
     */
    public function testWithRegistrationAccessFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRegistrationAccessAccessorUnitTest();

        // Act
        $result = $holder->withRegistrationAccess('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->registrationAccess()->value());
    }
    public function testChangedRegistrationAccess(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRegistrationAccessAccessorUnitTest();
        $original = $holder->withRegistrationAccess('one');
        $same = $holder->withRegistrationAccess('one');
        $modified = $holder->withRegistrationAccess('other');

        // Act
        $unchanged = $holder->isRegistrationAccessChanged();
        $withSame = $original->isRegistrationAccessChanged($same);
        $withDiferent = $original->isRegistrationAccessChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientRegistrationAccessAccessorUnitTest
{
    use TrustedClientRegistrationAccessAccessor;
}
